import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { useContext } from "react";
import { AuthContext } from "../context/AuthContext";
import { Bar, Pie } from "react-chartjs-2";
import {
  Chart as ChartJS,
  ArcElement,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(
  ArcElement,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend
);

function AdminDashboard() {
  const { userId } = useContext(AuthContext);
  const [houses, setHouses] = useState([]);
  const [bookings, setBookings] = useState([]);

  const fetchHouses = useCallback(async () => {
    try {
      const response = await axios.get("http://localhost:5000/houses");
      setHouses(response.data);
    } catch (error) {
      console.error("Error fetching houses:", error);
    }
  }, []);

  const fetchBookings = useCallback(async () => {
    try {
      const response = await axios.get("http://localhost:5000/admin/bookings", {
        headers: { "user-id": userId },
      });
      setBookings(response.data);
    } catch (error) {
      console.error("Error fetching bookings:", error);
      alert("Failed to fetch bookings: " + error.response?.data?.message);
    }
  }, [userId]);

  useEffect(() => {
    fetchHouses();
    fetchBookings();
  }, [fetchHouses, fetchBookings]);

  const handleDelete = async (houseId) => {
    if (window.confirm("Are you sure you want to delete this house?")) {
      try {
        await axios.delete(
          `http://localhost:5000/admin/delete-house/${houseId}`,
          {
            headers: { "user-id": userId },
          }
        );
        setHouses(houses.filter((house) => house.id !== houseId));
      } catch (error) {
        console.error("Error deleting house:", error);
        alert("Failed to delete house: " + error.response?.data?.message);
      }
    }
  };

  // Visualization Data
  const areaBookings = bookings.reduce((acc, booking) => {
    const area = booking.house_address.split(",")[0]; // Assuming address starts with area
    acc[area] = (acc[area] || 0) + 1;
    return acc;
  }, {});

  const houseBookings = bookings.reduce((acc, booking) => {
    acc[booking.house_id] = (acc[booking.house_id] || 0) + 1;
    return acc;
  }, {});

  const ratedHouses = houses
    .filter((house) => house.rating) // Only include houses with ratings
    .sort((a, b) => b.rating - a.rating)
    .slice(0, 5);

  const areaChartData = {
    labels: Object.keys(areaBookings),
    datasets: [
      {
        label: "Bookings by Area",
        data: Object.values(areaBookings),
        backgroundColor: [
          "#FF6384",
          "#36A2EB",
          "#FFCE56",
          "#4BC0C0",
          "#9966FF",
        ],
      },
    ],
  };

  const houseChartData = {
    labels: Object.keys(houseBookings).map(
      (id) =>
        houses.find((h) => h.id === parseInt(id))?.address || `House ${id}`
    ),
    datasets: [
      {
        label: "Bookings by House",
        data: Object.values(houseBookings),
        backgroundColor: "#36A2EB",
      },
    ],
  };

  const ratingChartData = {
    labels: ratedHouses.map((house) => house.address),
    datasets: [
      {
        label: "Top Rated Houses (Average Rating)",
        data: ratedHouses.map((house) => house.rating),
        backgroundColor: "#FFCE56",
      },
    ],
  };

  return (
    <div style={{ padding: "2rem", textAlign: "center" }}>
      <h2>Admin Dashboard</h2>
      <p>Welcome, Admin! Manage houses and bookings here.</p>

      {/* Visualizations */}
      <div style={{ marginBottom: "2rem" }}>
        <h3>Booking Visualizations</h3>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            gap: "2rem",
          }}
        >
          <div style={{ width: "400px" }}>
            <h4>Bookings by Area</h4>
            <Pie data={areaChartData} />
          </div>
          <div style={{ width: "400px" }}>
            <h4>Bookings by House</h4>
            <Bar data={houseChartData} />
          </div>
          <div style={{ width: "400px" }}>
            <h4>Top Rated Houses</h4>
            <Bar data={ratingChartData} />
          </div>
        </div>
      </div>

      {/* Houses Section */}
      <div style={{ marginBottom: "2rem" }}>
        <h3>Houses</h3>
        {houses.length === 0 ? (
          <p>No houses available.</p>
        ) : (
          <ul style={{ listStyle: "none", padding: 0 }}>
            {houses.map((house) => (
              <li
                key={house.id}
                style={{ margin: "1rem 0", textAlign: "left" }}
              >
                {house.address} - ₹{house.price} ({house.house_type},{" "}
                {house.max_persons} persons, Rating:{" "}
                {house.rating ? house.rating.toFixed(1) : "N/A"})
                <button
                  onClick={() => handleDelete(house.id)}
                  style={{
                    marginLeft: "1rem",
                    backgroundColor: "red",
                    color: "white",
                    border: "none",
                    padding: "0.5rem",
                    borderRadius: "4px",
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Bookings Section */}
      <div>
        <h3>Bookings</h3>
        {bookings.length === 0 ? (
          <p>No bookings available.</p>
        ) : (
          <table
            style={{
              margin: "0 auto",
              borderCollapse: "collapse",
              width: "80%",
            }}
          >
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                  Booking ID
                </th>
                <th style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                  User
                </th>
                <th style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                  House
                </th>
                <th style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                  Price
                </th>
                <th style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                  Payment Status
                </th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => (
                <tr key={booking.booking_id}>
                  <td style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                    {booking.booking_id}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                    {booking.user_name}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                    {booking.house_address}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                    ₹{booking.house_price}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "0.5rem" }}>
                    {booking.payment_status}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

export default AdminDashboard;
